import { createHash, randomUUID } from "node:crypto";
import { err, ok, type Result } from "neverthrow";
import { logger } from "../logger.js";
import {
  DEPS_CACHE_VOLUME_TARGET,
  type ResourceLimits,
  type SandboxClient,
  type SandboxSession,
} from "../sandbox/index.js";
import { GitOpsError, gitShow } from "./git-ops.js";

const log = logger.child({ component: "skills.deps" });

/**
 * Filename for the hash-pinned lockfile committed alongside `skill.py`.
 * Generated by `uv pip compile --generate-hashes` against the manifest's
 * `dependencies`. See `design/skills.md` → Dependencies.
 */
export const REQUIREMENTS_LOCK_FILE = "requirements.lock";

export interface LockfileSnapshot {
  /** sha256 over the lockfile contents (UTF-8 bytes). */
  hash: string;
  /** Raw lockfile text. The dependency populator feeds this to `uv pip sync`. */
  contents: string;
}

export type LockfileReadError =
  | { kind: "missing"; message: string }
  | { kind: "empty"; message: string };

/**
 * Read `requirements.lock` at the given commit and snapshot it. Caller
 * decides whether the file is required based on `manifest.dependencies` —
 * an empty dependency list means no lockfile, no hash, populator skipped.
 *
 * Returns:
 *   - `ok(LockfileSnapshot)` when the file is present and non-empty.
 *   - `err({ kind: "missing" })` when git reports `file_not_found`.
 *   - `err({ kind: "empty" })` when the file is present but blank.
 *
 * Other git failures (unreadable repo, missing sha) propagate as thrown
 * `GitOpsError`s — they indicate infrastructure-level bugs, not author
 * mistakes the register flow can surface as `errors[]`.
 */
export async function readLockfileAtSha(
  repoPath: string,
  gitSha: string,
): Promise<Result<LockfileSnapshot, LockfileReadError>> {
  let contents: string;
  try {
    contents = await gitShow(repoPath, gitSha, REQUIREMENTS_LOCK_FILE);
  } catch (e) {
    if (e instanceof GitOpsError && e.code === "file_not_found") {
      return err({
        kind: "missing",
        message: `${REQUIREMENTS_LOCK_FILE} not found at ${gitSha}`,
      });
    }
    throw e;
  }
  if (contents.trim().length === 0) {
    return err({
      kind: "empty",
      message: `${REQUIREMENTS_LOCK_FILE} is empty at ${gitSha}`,
    });
  }
  return ok({
    hash: createHash("sha256").update(contents, "utf-8").digest("hex"),
    contents,
  });
}

/** Exposed so WASM-tier consumers re-hashing committed contents skip a git round-trip. */
export function hashLockfileContents(contents: string): string {
  return createHash("sha256").update(contents, "utf-8").digest("hex");
}

const LOCKFILE_SPEC_RE = /^([a-z0-9][a-z0-9._-]*?)==([a-zA-Z0-9.+!-]+)/i;

/** Parse `name==version` specs from `uv pip compile --generate-hashes` output. Order preserved. */
export function parseLockfilePackageSpecs(contents: string): readonly string[] {
  const specs: string[] = [];
  for (const rawLine of contents.split("\n")) {
    const match = LOCKFILE_SPEC_RE.exec(rawLine.trim());
    if (match) specs.push(`${match[1]}==${match[2]}`);
  }
  return specs;
}

/** `resolver_failed` → uv stderr (yanked / missing / typo). `transport_failed` → everything else. */
export type LockfileCompileError =
  | { kind: "resolver_failed"; message: string }
  | { kind: "transport_failed"; message: string };

export interface LockfileCompiler {
  /** Re-resolves `dependencies` via uv pip compile. Caller byte-compares against committed lockfile. */
  compile(dependencies: ReadonlyArray<string>): Promise<Result<string, LockfileCompileError>>;
}

const DEFAULT_COMPILE_RESOURCE_LIMITS: Required<ResourceLimits> = {
  cpus: 1,
  memory_bytes: 512 * 1024 * 1024,
  pids: 256,
  disk_bytes: 512 * 1024 * 1024,
};

/** Wall-clock cap for the compile container. Resolver runs are typically <2s. */
const DEFAULT_COMPILE_TIMEOUT_MS = 60_000;

/** stdout cap from `SANDBOX_EXEC_BUFFER_LIMIT`. Lockfiles fit comfortably. */
const MAX_LOCKFILE_BYTES = 1024 * 1024;

export interface SandboxLockfileCompilerOptions {
  sandbox: SandboxClient;
  image: string;
  /** Override per-test or per-resource-constrained host. */
  resourceLimits?: Partial<ResourceLimits>;
  /** Override the wall-clock cap. Defaults to 60s. */
  timeoutMs?: number;
  /**
   * Optional shared deps-cache volume. When set, the compile sandbox
   * mounts it at `/skill-venvs` and points `UV_CACHE_DIR` at the
   * `.uv-cache` subdir so wheel metadata fetched during compile lives
   * on the same volume the populator later uses. Without this, every
   * register re-fetches PyPI metadata from scratch (~5-30s per register
   * for non-trivial dep sets).
   */
  depsCacheVolumeName?: string;
}

/** Sandbox-backed LockfileCompiler. Fresh session per compile; ~1-2s spawn-dominated. */
export function makeSandboxLockfileCompiler(
  opts: SandboxLockfileCompilerOptions,
): LockfileCompiler {
  const limits: ResourceLimits = {
    cpus: opts.resourceLimits?.cpus ?? DEFAULT_COMPILE_RESOURCE_LIMITS.cpus,
    memory_bytes: opts.resourceLimits?.memory_bytes ?? DEFAULT_COMPILE_RESOURCE_LIMITS.memory_bytes,
    pids: opts.resourceLimits?.pids ?? DEFAULT_COMPILE_RESOURCE_LIMITS.pids,
    disk_bytes: opts.resourceLimits?.disk_bytes ?? DEFAULT_COMPILE_RESOURCE_LIMITS.disk_bytes,
  };
  const timeoutMs = opts.timeoutMs ?? DEFAULT_COMPILE_TIMEOUT_MS;

  return {
    async compile(
      dependencies: ReadonlyArray<string>,
    ): Promise<Result<string, LockfileCompileError>> {
      const taskId = `lockfile-compile-${randomUUID()}`;
      // Buffer for slightly longer than the exec budget so an exec
      // timeout fires first and the reaper has a margin to clean up
      // if the host crashes before delete().
      const expiresAt = new Date(Date.now() + timeoutMs + 30_000);

      // Backend startup folds into the same error envelope as the exec.
      let session: SandboxSession;
      try {
        await opts.sandbox.ensureImagePresent(opts.image, limits);
        session = await opts.sandbox.create({
          taskId,
          image: opts.image,
          resourceLimits: limits,
          expiresAt,
          ...(opts.depsCacheVolumeName && {
            depsCacheVolume: { volumeName: opts.depsCacheVolumeName },
            env: { UV_CACHE_DIR: `${DEPS_CACHE_VOLUME_TARGET}/.uv-cache` },
          }),
        });
      } catch (e) {
        return err({
          kind: "transport_failed",
          message: e instanceof Error ? e.message : String(e),
        });
      }

      try {
        // `--no-header` drops uv's "autogenerated by …" preamble — the
        // command-line text differs between the author's invocation
        // (`uv pip compile requirements.in -o requirements.lock`) and
        // ours (`uv pip compile -`), so its presence would mask
        // byte-identical resolver output as stale. Authors must use
        // the same flag — documented in `design/skills.md`.
        const handle = await session.execStreaming(
          ["uv", "pip", "compile", "--generate-hashes", "--no-header", "--quiet", "-"],
          { attachStdin: true, timeoutMs },
        );
        if (!handle.stdin) {
          await handle.dispose().catch(() => {});
          return err({
            kind: "transport_failed",
            message: "execStreaming returned without stdin despite attachStdin=true",
          });
        }

        const stdoutChunks: Buffer[] = [];
        const stderrChunks: string[] = [];
        let stdoutBytes = 0;
        let truncated = false;
        // Unhandled stream `'error'` events crash the host process.
        let streamError: Error | undefined;
        const captureError = (e: Error): void => {
          if (!streamError) streamError = e;
        };
        handle.stdout.on("error", captureError);
        handle.stderr.on("error", captureError);
        handle.stdin.on("error", captureError);
        handle.stdout.on("data", (chunk: Buffer) => {
          if (truncated) return;
          if (stdoutBytes + chunk.length > MAX_LOCKFILE_BYTES) {
            truncated = true;
            // Abort the exec so uv stops writing — otherwise it blocks
            // on its pipe buffer until timeoutMs (60s) fires.
            handle.dispose().catch(() => {});
            return;
          }
          stdoutBytes += chunk.length;
          stdoutChunks.push(chunk);
        });
        handle.stderr.setEncoding("utf-8");
        handle.stderr.on("data", (chunk: string) => stderrChunks.push(chunk));

        handle.stdin.write(`${dependencies.join("\n")}\n`);
        handle.stdin.end();

        const { exitCode } = await handle.wait();
        if (streamError) {
          return err({
            kind: "transport_failed",
            message: `stream error: ${streamError.message}`,
          });
        }
        if (truncated) {
          return err({
            kind: "transport_failed",
            message: `uv pip compile output exceeded ${MAX_LOCKFILE_BYTES} bytes — declared deps produce an unexpectedly large lockfile`,
          });
        }
        if (exitCode !== 0) {
          return err({
            kind: "resolver_failed",
            message: stderrChunks.join("").trim() || `uv pip compile exited ${exitCode}`,
          });
        }
        return ok(Buffer.concat(stdoutChunks).toString("utf-8"));
      } catch (e) {
        return err({
          kind: "transport_failed",
          message: e instanceof Error ? e.message : String(e),
        });
      } finally {
        await opts.sandbox.delete(session).catch((e: unknown) => {
          log.warn(
            { taskId, err: e instanceof Error ? e.message : String(e) },
            "lockfile compile: sandbox.delete failed",
          );
        });
      }
    },
  };
}

/**
 * Per-task wall-clock cap for the populate exec. Default uv pip sync
 * over a typical skill's lockfile (HTTP-only deps) finishes in
 * single-digit seconds; bigger trees (anything pulling cryptography,
 * pandas, etc.) need more. Tuned conservatively so the first invoke
 * doesn't time out on a cold populate path.
 */
const DEFAULT_POPULATE_TIMEOUT_MS = 180_000;

/**
 * Shell program that the populator invokes inside the worker
 * container. Idempotent: if `$VENV/.ready` exists, exits 0 immediately.
 * Otherwise creates a tmp venv adjacent to the target, syncs the
 * lockfile via stdin, plants the marker, and renames into place.
 *
 * The rename is the atomic-publish point — readers gate on `.ready`,
 * so partial populates (process killed mid-sync, tmp dir left behind)
 * never get observed as live. The rm -rf at the top covers a
 * crash-and-retry on the same worker where the tmp dir from the
 * previous attempt is still present.
 *
 * Cross-worker race safety: when `/skill-venvs` is a shared Docker
 * volume mounted on every pool worker, two workers can populate the
 * same hash in parallel. Both check `.ready` (missing), both `uv
 * venv` into distinct `<HASH>.tmp.<workerId>` dirs, both run sync,
 * both rename. POSIX `mv` of a directory onto an existing non-empty
 * directory fails EEXIST — the first rename publishes the venv, the
 * second sees the publication and treats it as success after
 * confirming `.ready` is present on the winning copy. No advisory
 * lock needed; the marker file is the synchronisation point.
 *
 * Args are positional: $1 = lockfile hash, $2 = worker id (used for
 * the tmp-dir suffix; per-worker uniqueness is sufficient because
 * each container is single-flight on its supervisor).
 */
const POPULATE_SCRIPT = `set -eu
HASH="$1"
WORKERID="$2"
# Compute the runtime's Python ABI inline so the venv path varies
# with the image's Python version. An image bump from python:3.14 to
# python:3.15 produces a different PY_ABI -> different VENV path ->
# fresh populate; the stale 3.14 dir orphans and the reaper cleans
# it up on its next tick. The supervisor reads its own
# sys.version_info to construct the same path on activation.
#
# Assumes the runtime image exposes a \`python3\` binary on PATH.
# True today (python:3.14-slim base); a hypothetical Python 4 image
# that renamed the binary to \`python4\` would need this line
# updated. Major-in-suffix already protects the cache key, so the
# only impact would be the script failing at this line vs at first
# import.
#
# Command substitution runs synchronously and produces no side
# effects on stdin, so PY_ABI completes before \`uv pip sync\` reads
# the lockfile body. If a future change adds an earlier
# stdin-consuming step, move this line above it to preserve that
# ordering.
PY_ABI=$(python3 -c "import sys; print(f'py{sys.version_info.major}.{sys.version_info.minor}')")
VENV="${DEPS_CACHE_VOLUME_TARGET}/$HASH-$PY_ABI"
TMP="${DEPS_CACHE_VOLUME_TARGET}/$HASH-$PY_ABI.tmp.$WORKERID"
# Dotted so it can't be mistaken for a lockfile-hash dir (sha256 hex
# never starts with .). Shared filesystem with venvs lets uv hardlink.
export UV_CACHE_DIR="${DEPS_CACHE_VOLUME_TARGET}/.uv-cache"
if [ -f "$VENV/.ready" ]; then
  exit 0
fi
mkdir -p "${DEPS_CACHE_VOLUME_TARGET}" "$UV_CACHE_DIR"
# Opportunistic reaper of orphaned tmp dirs from earlier crashed
# populates on other workers. Same-worker crash is already covered by
# the rm -rf "$TMP" below; this one catches the cross-worker case on
# the shared volume.
find "${DEPS_CACHE_VOLUME_TARGET}" -maxdepth 1 -name '*.tmp.*' -mmin +10 -exec rm -rf {} + 2>/dev/null || true
rm -rf "$TMP"
uv venv --quiet "$TMP"
uv pip sync --quiet --python "$TMP/bin/python" --require-hashes --only-binary=:all: /dev/stdin
touch "$TMP/.ready"
# -T (no-target-directory) makes mv fail rather than nest TMP inside
# an existing VENV. Capture stderr so disk-full / permission failures
# surface as themselves, not as the recovery branch's misleading
# "lost rename race".
if ! MV_ERR=$(mv -T "$TMP" "$VENV" 2>&1); then
  if [ -f "$VENV/.ready" ]; then
    rm -rf "$TMP"
    exit 0
  fi
  echo "populate_failed: rename $TMP → $VENV failed and $VENV is not ready: $MV_ERR" >&2
  rm -rf "$TMP"
  exit 1
fi
`;

/**
 * Outcome of `ensureVenvPopulated`. `populate_failed` carries the
 * sync's stderr — usually a hash-mismatch (someone tampered with the
 * lockfile), a yanked wheel, or a Pyodide-incompatible package the
 * register-time compile somehow let through. `transport_failed` is
 * everything else: exec couldn't launch, timed out, etc.
 */
export type VenvPopulateError =
  | { kind: "populate_failed"; message: string }
  | { kind: "transport_failed"; message: string };

export interface EnsureVenvPopulatedOptions {
  session: SandboxSession;
  lockfileHash: string;
  lockfileContents: string;
  /**
   * Stable identifier for the calling worker. Used to suffix the tmp
   * populate directory (`<hash>.tmp.<workerId>`) so concurrent populators
   * on the shared `/skill-venvs` volume target distinct tmp dirs.
   * Cross-worker concurrency is resolved at the rename step (`mv -T`
   * fails on a non-empty target; the loser sees `.ready` on the
   * winner's published dir and exits success).
   */
  workerId: string;
  timeoutMs?: number;
}

/**
 * Ensure a per-lockfile-hash virtualenv exists at
 * `/skill-venvs/<hash>-py<major>.<minor>/` on the shared deps-cache
 * volume. Idempotent -- the second call (or any concurrent call
 * ordered after a successful one) no-ops via the `.ready` marker.
 *
 * The path includes the runtime's Python ABI so an image bump that
 * changes Python minor populates a fresh venv (and orphans the old
 * one for the reaper). The host doesn't need to know the image's
 * ABI: the populate script computes it inline from
 * `python3 -c "...sys.version_info..."`, and the supervisor reads its
 * own `sys.version_info` to construct the same path on activation.
 * Same image, same Python -> same path, by construction.
 *
 * The venv lives on the `/skill-venvs` Docker / Daytona volume shared
 * across every tier-2 worker the pool spawns: a venv populated by one
 * worker is reused by every subsequent worker and survives recycle.
 * Cross-worker concurrency on the same `(hash, ABI)` pair is
 * serialised by `.ready` + `mv -T` rename failure; see
 * `POPULATE_SCRIPT` below.
 */
export async function ensureVenvPopulated(
  opts: EnsureVenvPopulatedOptions,
): Promise<Result<void, VenvPopulateError>> {
  const timeoutMs = opts.timeoutMs ?? DEFAULT_POPULATE_TIMEOUT_MS;

  // `sh -c <script> <argv0> <args...>` runs the script with the
  // trailing values bound to $0/$1/$2. Lockfile body goes through
  // stdin (uv pip sync reads /dev/stdin). Buffered exec doesn't
  // expose stdin, so this has to be streaming.
  let handle: Awaited<ReturnType<SandboxSession["execStreaming"]>>;
  try {
    handle = await opts.session.execStreaming(
      ["sh", "-c", POPULATE_SCRIPT, "populate", opts.lockfileHash, opts.workerId],
      { attachStdin: true, timeoutMs },
    );
  } catch (e) {
    return err({
      kind: "transport_failed",
      message: e instanceof Error ? e.message : String(e),
    });
  }
  if (!handle.stdin) {
    await handle.dispose().catch(() => {});
    return err({
      kind: "transport_failed",
      message: "execStreaming returned without stdin despite attachStdin=true",
    });
  }

  // Script runs with `--quiet` flags everywhere; uv stays silent
  // on stdout under normal operation. Stderr captures the diagnostic
  // surface (hash mismatch, yanked wheel, etc.) we surface back to
  // the host.
  const stderrChunks: string[] = [];
  handle.stdout.on("data", () => {
    // Drain — script is `--quiet`. Any bytes here are uv-version
    // diagnostic noise we don't bubble up.
  });
  handle.stderr.setEncoding("utf-8");
  handle.stderr.on("data", (c: string) => stderrChunks.push(c));

  handle.stdin.write(opts.lockfileContents);
  handle.stdin.end();

  let exitCode: number;
  try {
    ({ exitCode } = await handle.wait());
  } catch (e) {
    return err({
      kind: "transport_failed",
      message: e instanceof Error ? e.message : String(e),
    });
  }
  if (exitCode !== 0) {
    return err({
      kind: "populate_failed",
      message: stderrChunks.join("").trim() || `uv pip sync exited ${exitCode}`,
    });
  }
  return ok(undefined);
}
